(()=>{
 const previous=render;
 render=function(){const selectedPage=page;if(selectedPage==='rollout-readiness')page='overview';previous();page=selectedPage;if(!nodeUser||nodeUser.role!=='admin')return;
  const branch=document.querySelector('#branch');if(branch){const selected=branch.value;const choices=['كل الفروع',...new Set((db.branches||[]).map(b=>b.name))];branch.innerHTML=choices.map(b=>'<option>'+esc(b)+'</option>').join('');branch.value=choices.includes(selected)?selected:'كل الفروع';}
  const nav=document.querySelector('#nav');if(nav&&!nav.querySelector('[data-readiness]')){const b=document.createElement('button');b.dataset.readiness='1';b.innerHTML='<i>'+navIcon('rollout')+'</i> تجهيز حسابات الموظفين';b.onclick=()=>{page='rollout-readiness';render()};nav.append(b);}
  if(page!=='rollout-readiness')return;
  const people=(db.staff||[]).filter(s=>s.legacyProfileId),unlinked=people.filter(s=>s.needsActivation),incomplete=people.filter(s=>s.needsReview);
  document.querySelector('#app').innerHTML='<section class="shiftplanner"><h2>تجهيز حسابات الموظفين</h2><p>ملف الموظف المستورد لا ينشئ كلمة مرور أو يمنح دخولًا تلقائيًا. يسجل الموظف حسابه، ثم تختار الإدارة ملفه القديم أثناء الموافقة لربط مهامه وسجلاته.</p><p>ملفات مستوردة: '+people.length+' · تحتاج تفعيل: '+unlinked.length+' · بيانات تحتاج مراجعة: '+incomplete.length+'</p><div class="table-wrap"><table><thead><tr><th>الموظف / الكود</th><th>القسم</th><th>الفرع</th><th>التجهيز</th></tr></thead><tbody>'+people.map(s=>'<tr><td>'+esc(s.name)+'<br>'+esc(s.employeeCode||'بدون كود')+'</td><td>'+esc(s.department)+'</td><td>'+esc(s.branch)+'</td><td>'+(s.needsActivation?'ينتظر تسجيل وربط الحساب':'مرتبط بحساب')+(s.needsReview?' · يلزم مراجعة الفرع / القسم':'')+'</td></tr>').join('')+'</tbody></table></div><button id="readinessApprovals">مراجعة وربط طلبات التسجيل</button><hr><h3>البروفايلات المزدوجة</h3><p>للموظف اللي له أكثر من دور (زي HR + أسسمنت): أنشئ ملف بروفايل إضافي للموظف من صفحة الفريق، ثم اربطه بحسابه من هنا. الموظف يلاقي قائمة تبديل بين بروفايلاته أعلى الشاشة، والحضور والمهام بتتسجل على البروفايل المختار.</p><label>الحساب <select id="plinkAccount">'+(db.staff||[]).filter(s=>s.cloudId).map(s=>'<option value="'+s.id+'">'+esc(s.name)+' — '+esc(s.position||'')+'</option>').join('')+'</select></label><div id="plinkList"></div><label>إضافة بروفايل <select id="plinkRow">'+(db.staff||[]).filter(s=>!s.cloudId).map(s=>'<option value="'+s.id+'">'+esc(s.name)+' — '+esc(s.position||'')+' — '+esc(s.branch||'')+'</option>').join('')+'</select></label> <button id="plinkAdd">ربط البروفايل بالحساب</button><hr><h3>إنشاء بروفايل دور إضافي</h3><p>ينشئ ملف دور إضافي لنفس الشخص (بنفس الاسم والفرع) ويربطه بالحساب المختار. الحضور بيتحسب على الشخص كله مش على كل بروفايل: نفس سقف الساعات وعدد الشفتات. مفيش مرتب أو سعر ساعة بيتحط؛ سعر الساعة بيفضل غير محدد لحد ما يتحدد من صفحة المرتبات، وحضور البروفايل ده مش هيتحسب له أجر قبل كده.</p><label>الدور الإضافي <select id="pcreatePos">'+Object.keys(positions).filter(p=>roleForTitle(p)==='employee').map(p=>'<option value="'+esc(p)+'">'+esc(p)+'</option>').join('')+'</select></label> <label>اسم البروفايل (اختياري، لو دكتور أسسمنت اكتب نفس اسمه في جدول الدكاترة زي «دكتورة هنا» عشان يتربط بجدوله تلقائيًا) <input id="pcreateName" maxlength="120" placeholder="مثال: دكتورة هنا"></label> <button id="pcreateAdd">إنشاء وربط بالحساب المختار</button><hr><h3>تغيير اسم بروفايل إضافي</h3><label>البروفايل <select id="prenameRow">'+(db.staff||[]).filter(s=>s.profileOf&&!s.cloudId).map(s=>'<option value="'+s.id+'">'+esc(s.name)+' — '+esc(s.position||'')+'</option>').join('')+'</select></label> <label>الاسم الجديد <input id="prenameName" maxlength="120"></label> <button id="prenameBtn">تغيير الاسم</button></section>';
  document.querySelector('#readinessApprovals').onclick=()=>{page='join-approvals';render()};
  db.profileLinks=db.profileLinks||{};
  const paint=()=>{const acc=String(document.querySelector('#plinkAccount').value);const links=db.profileLinks[acc]||[];document.querySelector('#plinkList').innerHTML=links.length?'<ul>'+links.map(id=>{const s=(db.staff||[]).find(x=>String(x.id)===String(id));return '<li>'+esc(s?s.name+' — '+(s.position||''):id)+' <button data-unlink="'+id+'">فك الربط</button></li>'}).join('')+'</ul>':'<p>لا توجد بروفايلات مرتبطة بهذا الحساب.</p>';document.querySelectorAll('[data-unlink]').forEach(b=>b.onclick=()=>{db.profileLinks[acc]=links.filter(id=>String(id)!==String(b.dataset.unlink));audit('فك ربط بروفايل عن حساب '+acc);save();paint()})};
  document.querySelector('#plinkAccount').onchange=paint;document.querySelector('#prenameBtn').onclick=async()=>{const id=Number(document.querySelector('#prenameRow').value),nm=(document.querySelector('#prenameName').value||'').trim();if(!id||!nm)return toast('اختار البروفايل واكتب الاسم الجديد');if(!confirm('تغيير اسم البروفايل إلى «'+nm+'»؟ لو الاسم هو نفس اسم دكتور في جدول الأسسمنت هيتربط بجدوله.'))return;try{await nativeAction('profile_rename',{employeeId:id,name:nm});toast('تم تغيير الاسم')}catch(err){toast(err.message==='CONFLICT'?'فيه بروفايل بنفس الاسم والدور':err.message)}};document.querySelector('#pcreateAdd').onclick=async()=>{const acc=Number(document.querySelector('#plinkAccount').value),pos=document.querySelector('#pcreatePos').value;if(!acc||!pos)return;const sel=document.querySelector('#plinkAccount'),nm=sel.options[sel.selectedIndex].text;if(!confirm('إنشاء بروفايل «'+pos+'» وربطه بحساب '+nm+'؟ مفيش سعر ساعة هيتحط.'))return;try{const pn=(document.querySelector('#pcreateName').value||'').trim();await nativeAction('profile_create',pn?{accountId:acc,position:pos,profileName:pn}:{accountId:acc,position:pos});toast('تم إنشاء البروفايل وربطه (سعر الساعة غير محدد)')}catch(err){toast(err.message==='CONFLICT'?'البروفايل ده موجود بالفعل لنفس الحساب':err.message==='INVALID_INPUT'?'اختار دور مختلف عن دور الحساب الأساسي':err.message)}};
  document.querySelector('#plinkAdd').onclick=()=>{const acc=String(document.querySelector('#plinkAccount').value),row=Number(document.querySelector('#plinkRow').value);if(!acc||!row)return;db.profileLinks[acc]=db.profileLinks[acc]||[];if(db.profileLinks[acc].some(id=>Number(id)===row))return toast('البروفايل مرتبط بالفعل');db.profileLinks[acc].push(row);const s=(db.staff||[]).find(x=>Number(x.id)===row);audit('ربط بروفايل '+(s?s.name:row)+' بحساب '+acc);save();paint();toast('تم ربط البروفايل')};
  paint();
 };
})();
